#!/usr/bin/env python3
"""Installs every munch-clone update in the right order:
  1 M-Pesa only   2 admin login & accounts   3 super admin
  4 menu items    5 opening hours & promos  6 loyal-customer promos  7 loyalty points  8 private loyalty rules  9 DMC Foods themes  10 M-Pesa till  11 Render + checkout payment screen  12 DMC Flavours name
Safe to run more than once (steps already done are skipped).
Run from the munch-clone folder:   python3 install_all.py
"""
import base64, os, subprocess, sys, tempfile
if not (os.path.isdir("server/src") and os.path.isdir("client/src")):
    sys.exit("Run this from the munch-clone folder (the one with server/ and client/).")
ORDER = ['mpesa_only.py', 'admin_accounts.py', 'super_admin.py', 'menu_items.py', 'hours_promos.py', 'promo_loyal.py', 'loyalty_points.py', 'loyalty_private.py', 'brand_themes.py', 'mpesa_till.py', 'render_mpesa.py', 'rebrand_flavours.py']
SCRIPTS = {'rebrand_flavours.py': '', 'render_mpesa.py': '', 'mpesa_till.py': '', 'brand_themes.py': '', 'loyalty_private.py': '', 'loyalty_points.py': '', 'mpesa_only.py': '', 'admin_accounts.py': '', 'super_admin.py': '', 'menu_items.py': '', 'hours_promos.py': '', 'promo_loyal.py': ''}
tmp = tempfile.mkdtemp()
def has(path, text=None):
    if not os.path.exists(path): return False
    return text is None or text in open(path).read()

DONE = {
    "mpesa_only.py":     lambda: not has("server/src/routes/stripe.js") and not has("client/src/components/PaystackModal.jsx"),
    "admin_accounts.py": lambda: has("server/src/routes/adminAuth.js"),
    "super_admin.py":    lambda: has("server/src/routes/superAdmin.js"),
    "menu_items.py":     lambda: has("server/src/models/MenuItem.js", "addonItems"),
    "hours_promos.py":   lambda: has("server/src/lib/hours.js"),
    "promo_loyal.py":    lambda: has("server/src/models/PromoCode.js", "eligibility"),
    "loyalty_points.py": lambda: has("server/src/lib/loyalty.js"),
    "rebrand_flavours.py": lambda: has("client/src/theme.js", "DMC Flavours") and has("client/src/components/BrandMark.jsx", "sm:text-[17px]"),
    "render_mpesa.py":   lambda: has("render.yaml") and has("client/src/components/MpesaWaiting.jsx"),
    "mpesa_till.py":     lambda: has("server/src/lib/mpesa.js"),
    "brand_themes.py":   lambda: has("client/src/theme.js") and has("client/src/index.css", "lucide-heart"),
    "loyalty_private.py": lambda: has("client/src/pages/Checkout.jsx", "loyalty?.enabled &&") and not has("client/src/components/ProductDetailModal.jsx", "loyaltyRules") and has("client/src/pages/Checkout.jsx", "const { user } = useAuth();\n  const [usePoints"),
}

for i, name in enumerate(ORDER, 1):
    if DONE[name]():
        print(f"\n===== Step {i}/{len(ORDER)}: {name} =====\nalready installed — skipped")
        continue
    path = os.path.join(tmp, name)
    open(path, "wb").write(base64.b64decode(SCRIPTS[name]))
    print(f"\n===== Step {i}/{len(ORDER)}: {name} =====")
    r = subprocess.run([sys.executable, path], capture_output=True, text=True)
    out = (r.stdout + r.stderr).strip()
    fails = [l for l in out.splitlines() if "[FAIL]" in l or "Run " in l and "first" in l]
    if r.returncode != 0 or fails:
        print(out)
        sys.exit(f"\nStopped at step {i} ({name}). Send this output to Claude.")
    print("\n".join(l for l in out.splitlines() if l.startswith(("[ok]", "[write]", "[deleted]"))) or (out.splitlines()[-1] if out else "already done"))
print("""
===== All done =====
Next:
  cd server && npm install
  npm run admin -- create 0793935384 "Admin" 0793935384   (needs MongoDB running)
  then restart the server, and rebuild the client (cd ../client && npm run build)
""")
